/*
 * Dog breeding calculators for mintwavestudio.com.
 *
 * The maths is a port of the Sire & Dam app (sire_dam/lib/domain/repro.dart) and gives the same
 * results as its tests. Pages are generated by sire_dam/tools/web/site_pages.py.
 *
 * Mount: <div data-sd-calc="pregnancy|progesterone|heat|puppy"></div>
 * Text:  <script type="application/json" id="sd-i18n">{...}</script> (all words come from the page)
 * Dates are handled as UTC day numbers, so daylight saving changes never shift a date.
 */
(function () {
  "use strict";

  /* ------------------------------------------------------------------ maths (same as the app) */

  const DAY = 86400000;
  const dayNum = iso => {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso || "");
    return m ? Math.round(Date.UTC(+m[1], +m[2] - 1, +m[3]) / DAY) : null;
  };
  const isoOf = n => new Date(n * DAY).toISOString().slice(0, 10);
  const addDays = (iso, d) => isoOf(dayNum(iso) + d);
  const daysBetween = (a, b) => dayNum(b) - dayNum(a);

  const DEFAULT_HEAT_INTERVAL = 183;

  /* Average gap between heats (start dates, any order); gaps outside 90–456 days are ignored,
     and only the last four gaps count. Null with fewer than two usable dates. */
  function averageHeatInterval(starts) {
    const s = starts.filter(Boolean).slice().sort();
    const gaps = [];
    for (let i = 1; i < s.length; i++) gaps.push(daysBetween(s[i - 1], s[i]));
    const ok = gaps.filter(g => g >= 90 && g <= 456);
    if (!ok.length) return null;
    const recent = ok.length > 4 ? ok.slice(ok.length - 4) : ok;
    return Math.round(recent.reduce((a, b) => a + b, 0) / recent.length);
  }

  function predictNextHeat(starts) {
    const s = starts.filter(Boolean);
    if (!s.length) return null;
    const last = s.slice().sort()[s.length - 1];
    return addDays(last, averageHeatInterval(s) ?? DEFAULT_HEAT_INTERVAL);
  }

  const NMOL_PER_NG = 3.18;

  function p4Stage(ng) {
    return ng < 1.5 ? "baseline" : ng < 4.0 ? "lhSurge" : ng < 10 ? "ovulation" : "fertile";
  }

  /* First test at 4 ng/mL or more; otherwise 2 days after the first test at 1.5 or more. */
  function estimateOvulation(tests) {
    const s = tests.filter(t => t && t.date && isFinite(t.ng)).slice().sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
    for (const t of s) if (t.ng >= 4.0) return t.date;
    for (const t of s) if (t.ng >= 1.5) return addDays(t.date, 2);
    return null;
  }

  /* Best days to breed, as [first, last] days after ovulation. */
  const BREEDING_WINDOW = { natural: [1, 4], fresh: [1, 4], chilled: [2, 4], frozen: [3, 4] };

  function dueDate(opts) {
    if (opts.ovulation) {
      const o = opts.ovulation;
      return { due: addDays(o, 63), earliest: addDays(o, 62), latest: addDays(o, 64), fromOvulation: true };
    }
    if (opts.firstMating) {
      const m = opts.firstMating;
      return { due: addDays(m, 63), earliest: addDays(m, 58), latest: addDays(m, 68), fromOvulation: false };
    }
    return null;
  }

  const PREGNANCY_STEPS = [
    ["ultrasound", 28],
    ["moreFood", 35],
    ["xray", 55],
    ["whelpingBox", 56],
    ["temperature", 58],
    ["due", 63]
  ];

  /* Birth weight vs. a later weight. Loss after day 2 or not doubled by day 10 is flagged. */
  function puppyCheck(birthGrams, nowGrams, ageDays) {
    const change = (nowGrams - birthGrams) / birthGrams * 100;
    const perDay = ageDays > 0 ? change / ageDays : null;
    let flag = "ok";
    if (ageDays > 2 && nowGrams < birthGrams) flag = "lost";
    else if (ageDays >= 10 && nowGrams < birthGrams * 2) flag = "slow";
    return { change, perDay, target10: birthGrams * 2, flag };
  }

  const api = {
    dayNum, isoOf, addDays, daysBetween, DEFAULT_HEAT_INTERVAL, averageHeatInterval, predictNextHeat,
    NMOL_PER_NG, p4Stage, estimateOvulation, BREEDING_WINDOW, dueDate, PREGNANCY_STEPS, puppyCheck
  };
  if (typeof module !== "undefined" && module.exports) {
    module.exports = api;
    return;
  }

  /* ------------------------------------------------------------------ browser UI */

  const i18nEl = document.getElementById("sd-i18n");
  if (!i18nEl) return;
  const T = JSON.parse(i18nEl.textContent);
  const lang = document.documentElement.lang || "en";

  const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const fill = (s, v) => String(s).replace(/\{(\w+)\}/g, (m, k) => (k in v ? v[k] : m));
  const store = {
    get(k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
    set(k, v) { try { localStorage.setItem(k, v); } catch (e) { /* private mode */ } }
  };
  const params = new URLSearchParams(location.search);
  const todayIso = () => {
    const d = new Date();
    return isoOf(Math.round(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / DAY));
  };
  const fmtLong = new Intl.DateTimeFormat(T.locale || lang, { weekday: "long", day: "numeric", month: "long", year: "numeric", timeZone: "UTC" });
  const fmtShort = new Intl.DateTimeFormat(T.locale || lang, { weekday: "short", day: "numeric", month: "short", timeZone: "UTC" });
  const long = iso => fmtLong.format(new Date(dayNum(iso) * DAY));
  const short = iso => fmtShort.format(new Date(dayNum(iso) * DAY));
  const nf = (n, d) => new Intl.NumberFormat(T.locale || lang, { minimumFractionDigits: d, maximumFractionDigits: d }).format(n);
  const setUrl = q => { try { history.replaceState(null, "", location.pathname + "?" + q); } catch (e) { /* file:// */ } };

  function actions(withIcs) {
    return `<div class="calc-actions">
        ${withIcs ? `<button class="btn" type="button" data-act="ics">${esc(T.ics)}</button>` : ""}
        <button class="btn ghost" type="button" data-act="print">${esc(T.print)}</button>
        <button class="btn ghost" type="button" data-act="copy">${esc(T.copy)}</button>
      </div>
      <p class="calc-status" role="status"></p>`;
  }

  function bindActions(host, icsFn) {
    host.addEventListener("click", e => {
      const act = e.target.closest("[data-act]")?.dataset.act;
      if (!act) return;
      const status = host.querySelector(".calc-status");
      if (act === "print") window.print();
      if (act === "copy" && navigator.clipboard) {
        navigator.clipboard.writeText(location.href).then(() => { if (status) status.textContent = T.copied; }, () => {});
      }
      if (act === "ics" && icsFn) {
        const file = icsFn();
        if (!file) return;
        const a = document.createElement("a");
        a.href = URL.createObjectURL(new Blob([file.text], { type: "text/calendar" }));
        a.download = file.name;
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(a.href), 1000);
        if (status) status.textContent = T.icsDone;
      }
    });
  }

  function ics(events, prodName) {
    const stamp = new Date().toISOString().replace(/[-:]/g, "").replace(/\.\d+/, "");
    const clean = s => String(s).replace(/[\\;,]/g, m => "\\" + m).replace(/\n/g, "\\n");
    const lines = ["BEGIN:VCALENDAR", "VERSION:2.0", `PRODID:-//MintWave Studio//${prodName}//EN`, "CALSCALE:GREGORIAN"];
    events.forEach((ev, i) => {
      lines.push(
        "BEGIN:VEVENT",
        `UID:${ev.date.replace(/-/g, "")}-${prodName.replace(/\W/g, "")}-${i}@mintwavestudio.com`,
        `DTSTAMP:${stamp}`,
        `DTSTART;VALUE=DATE:${ev.date.replace(/-/g, "")}`,
        `DTEND;VALUE=DATE:${addDays(ev.date, 1).replace(/-/g, "")}`,
        `SUMMARY:${clean(ev.title)}`,
        `DESCRIPTION:${clean(ev.desc || "")}`,
        "TRANSP:TRANSPARENT",
        "END:VEVENT"
      );
    });
    lines.push("END:VCALENDAR");
    return lines.join("\r\n") + "\r\n";
  }

  /* ---------------- pregnancy / whelping date ---------------- */

  function pregnancy(host) {
    const P = T.preg;
    const initMode = params.get("from") === "ovulation" ? "ovulation" : (params.get("from") === "mating" ? "mating" : (store.get("sd.preg.from") || "mating"));
    const initDate = dayNum(params.get("date")) != null ? params.get("date") : addDays(todayIso(), -21);
    host.innerHTML = `
      <form class="calc" onsubmit="return false">
        <div class="calc-mode" role="radiogroup" aria-label="${esc(P.modeLabel)}">
          <label><input type="radio" name="from" value="mating"><span>${esc(P.modeMating)}</span></label>
          <label><input type="radio" name="from" value="ovulation"><span>${esc(P.modeOvulation)}</span></label>
        </div>
        <div class="calc-fields">
          <label class="field"><span data-label></span><input type="date" name="date" required></label>
        </div>
        <div class="calc-result" aria-live="polite"></div>
      </form>`;
    const form = host.querySelector("form");
    const dateIn = form.elements.date;
    const out = host.querySelector(".calc-result");
    form.querySelector(`input[value="${initMode}"]`).checked = true;
    dateIn.value = initDate;
    let current = null;

    function render() {
      const from = form.querySelector('input[name="from"]:checked').value;
      host.querySelector("[data-label]").textContent = from === "mating" ? P.fMating : P.fOvulation;
      const d0 = dayNum(dateIn.value) != null ? dateIn.value : null;
      if (!d0) { out.innerHTML = ""; current = null; return; }
      const est = dueDate(from === "mating" ? { firstMating: d0 } : { ovulation: d0 });
      const today = todayIso();
      const day = daysBetween(d0, today);
      const left = daysBetween(today, est.due);

      let status;
      if (day === -1) status = P.before1;
      else if (day < 0) status = fill(P.before, { n: -day });
      else if (left > 1) status = fill(P.dayOf, { d: day }) + " " + fill(P.dueIn, { n: left });
      else if (left === 1) status = fill(P.dayOf, { d: day }) + " " + P.dueTomorrow;
      else if (left === 0) status = P.dueToday;
      else if (daysBetween(today, est.latest) >= 0) status = fill(P.dayOf, { d: day });
      else status = P.past;

      const rows = [{ day: 0, key: "start", title: from === "mating" ? P.startMating : P.startOvulation, sub: from === "mating" ? P.startMatingS : P.startOvulationS }];
      PREGNANCY_STEPS.forEach(([k, d]) => rows.push({ day: d, key: k, title: P.steps[k], sub: k === "due" && from === "mating" ? P.dueMatingS : P.hints[k] }));
      const lastDay = daysBetween(d0, est.latest);
      rows.push({ day: lastDay, key: "latest", title: P.latest, sub: P.latestS });
      rows.forEach(r => { r.date = addDays(d0, r.day); });
      current = { from, d0, rows };

      const pct = Math.max(0, Math.min(100, day / 63 * 100));
      out.innerHTML = `
        <div class="result-hero"><span class="label">${esc(P.due)}</span><span class="date">${esc(long(est.due))}</span></div>
        <p class="result-sub">${esc(fill(P.window, { a: short(est.earliest), b: short(est.latest) }))} · ${esc(est.fromOvulation ? P.fromOv : P.fromMating)}<br>${esc(status)}</p>
        <div class="progress" aria-hidden="true"><div style="width:${pct.toFixed(1)}%"></div></div>
        <ol class="timeline">
          ${rows.map(r => {
            const cls = r.day < day ? "past" : (r.day === day ? "today" : "");
            return `<li class="${cls}"><span class="day">${esc(fill(P.day, { d: r.day }))}</span>
              <span class="what">${esc(r.title)}<small>${esc(r.sub)}</small></span>
              <span class="when">${esc(short(r.date))}</span></li>`;
          }).join("")}
        </ol>
        ${actions(true)}`;
      setUrl(new URLSearchParams({ from, date: d0 }).toString());
      store.set("sd.preg.from", from);
    }

    bindActions(host, () => current && {
      name: `whelping-${current.d0}.ics`,
      text: ics(current.rows.map(r => ({ date: r.date, title: P.calPrefix + r.title + " (" + fill(P.day, { d: r.day }) + ")", desc: r.sub })), "Dog pregnancy calculator")
    });
    form.addEventListener("change", render);
    dateIn.addEventListener("input", render);
    render();
  }

  /* ---------------- progesterone / ovulation ---------------- */

  function progesterone(host) {
    const P = T.p4;
    const unitInit = params.get("unit") === "nmol" ? "nmol" : (store.get("sd.p4.unit") || "ng");
    const methodInit = BREEDING_WINDOW[params.get("method")] ? params.get("method") : "natural";
    let tests = (params.get("t") || "").split(",").map(s => s.split(":")).filter(p => dayNum(p[0]) != null && isFinite(parseFloat(p[1])))
      .map(p => ({ date: p[0], v: p[1] }));
    if (!tests.length) {
      const t = todayIso();
      tests = [{ date: addDays(t, -4), v: "" }, { date: addDays(t, -2), v: "" }, { date: t, v: "" }];
    }

    host.innerHTML = `
      <form class="calc" onsubmit="return false">
        <div class="calc-fields">
          <label class="field">${esc(P.fUnit)}<select name="unit"><option value="ng">ng/mL</option><option value="nmol">nmol/L</option></select></label>
          <label class="field">${esc(P.fMethod)}<select name="method">
            ${["natural", "fresh", "chilled", "frozen"].map(m => `<option value="${m}">${esc(P.methods[m])}</option>`).join("")}
          </select></label>
        </div>
        <div class="p4-tests" style="margin:18px 0 14px"></div>
        <div class="calc-actions"><button class="btn ghost" type="button" data-add>${esc(P.add)}</button></div>
        <div class="calc-result" aria-live="polite"></div>
      </form>`;
    const form = host.querySelector("form");
    const body = host.querySelector(".p4-tests");
    const out = host.querySelector(".calc-result");
    form.elements.unit.value = unitInit;
    form.elements.method.value = methodInit;

    function rowHtml(t) {
      return `<div class="p4-row" style="display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr) auto;gap:10px;align-items:end;padding:10px 0;border-bottom:1px solid var(--line)">
        <label class="field">${esc(P.cDate)}<input type="date" name="d" value="${esc(t.date)}"></label>
        <label class="field">${esc(P.cResult)}<input type="number" name="v" min="0" max="200" step="0.1" inputmode="decimal" value="${esc(t.v)}"></label>
        <button class="btn ghost" type="button" data-del aria-label="${esc(P.remove)}" style="min-width:44px;padding:0 12px">×</button>
        <span data-stage style="grid-column:1/-1;font-size:14px;font-weight:600;color:var(--teal)"></span>
      </div>`;
    }
    body.innerHTML = tests.map(rowHtml).join("");

    function read() {
      const unit = form.elements.unit.value;
      return [...body.querySelectorAll(".p4-row")].map(tr => {
        const date = tr.querySelector('[name="d"]').value;
        const raw = parseFloat(tr.querySelector('[name="v"]').value);
        const ng = isFinite(raw) ? (unit === "nmol" ? raw / NMOL_PER_NG : raw) : NaN;
        return { tr, date, raw, ng };
      });
    }

    function render() {
      const unit = form.elements.unit.value;
      const method = form.elements.method.value;
      const rows = read();
      rows.forEach(r => {
        const cell = r.tr.querySelector("[data-stage]");
        cell.textContent = isFinite(r.ng) && dayNum(r.date) != null ? `${P.cStage}: ${P.stages[p4Stage(r.ng)]}` : "";
      });
      const valid = rows.filter(r => isFinite(r.ng) && dayNum(r.date) != null);
      const q = new URLSearchParams({ unit, method, t: valid.map(r => `${r.date}:${r.raw}`).join(",") });
      setUrl(q.toString());
      store.set("sd.p4.unit", unit);
      if (!valid.length) { out.innerHTML = `<p class="result-sub">${esc(P.empty)}</p>`; return; }

      const latest = valid.slice().sort((a, b) => (a.date < b.date ? -1 : 1)).pop();
      const stage = p4Stage(latest.ng);
      const ov = estimateOvulation(valid.map(r => ({ date: r.date, ng: r.ng })));
      let html;
      if (!ov) {
        html = `<div class="result-hero"><span class="label">${esc(P.latest)}</span><span class="date">${esc(P.stages[stage])}</span></div>
          <p class="result-sub">${esc(P.advice[stage])}</p>`;
      } else {
        const [a, b] = BREEDING_WINDOW[method];
        const due = dueDate({ ovulation: ov });
        const surgeOnly = !valid.some(r => r.ng >= 4.0);
        html = `<div class="result-hero"><span class="label">${esc(P.ovulation)}</span><span class="date">${esc(long(ov))}</span></div>
          <p class="result-sub">${esc(surgeOnly ? P.ovFromSurge : P.ovFromTest)} ${esc(P.advice[stage])}</p>
          <div class="targets">
            <div class="target"><div class="k">${esc(fill(P.window, { m: P.methods[method] }))}</div><div class="v">${esc(short(addDays(ov, a)))} – ${esc(short(addDays(ov, b)))}</div><div class="k">${esc(fill(P.windowDays, { a, b }))}</div></div>
            <div class="target"><div class="k">${esc(P.due)}</div><div class="v">${esc(short(due.due))}</div><div class="k">${esc(fill(P.dueWindow, { a: short(due.earliest), b: short(due.latest) }))}</div></div>
            <div class="target"><div class="k">${esc(P.latest)}</div><div class="v">${esc(nf(latest.ng, 1))} ng/mL</div><div class="k">${esc(nf(latest.ng * NMOL_PER_NG, 1))} nmol/L · ${esc(P.stages[stage])}</div></div>
          </div>
          <p class="note"><a href="${esc(P.pregLink)}?from=ovulation&amp;date=${esc(ov)}">${esc(P.pregLinkText)}</a></p>`;
      }
      out.innerHTML = html + actions();
    }

    form.addEventListener("click", e => {
      if (e.target.closest("[data-add]")) {
        const rows = read();
        const last = rows.length ? rows[rows.length - 1].date : todayIso();
        body.insertAdjacentHTML("beforeend", rowHtml({ date: dayNum(last) != null ? addDays(last, 2) : todayIso(), v: "" }));
        render();
      }
      const del = e.target.closest("[data-del]");
      if (del && body.children.length > 1) { del.closest(".p4-row").remove(); render(); }
    });
    bindActions(host, null);
    form.addEventListener("change", render);
    form.addEventListener("input", render);
    render();
  }

  /* ---------------- heat cycle ---------------- */

  function heat(host) {
    const P = T.heat;
    let dates = (params.get("h") || "").split(",").filter(d => dayNum(d) != null);
    if (!dates.length) dates = [addDays(todayIso(), -150)];
    while (dates.length < 4) dates.push("");
    host.innerHTML = `
      <form class="calc" onsubmit="return false">
        <div class="calc-fields">
          ${dates.map((d, i) => `<label class="field">${esc(i === 0 ? P.fLast : fill(P.fEarlier, { n: i }))}<input type="date" name="h${i}" value="${esc(d)}"></label>`).join("")}
        </div>
        <div class="calc-result" aria-live="polite"></div>
      </form>`;
    const form = host.querySelector("form");
    const out = host.querySelector(".calc-result");
    let current = null;

    function render() {
      const starts = [0, 1, 2, 3].map(i => form.elements["h" + i].value).filter(d => dayNum(d) != null);
      setUrl(new URLSearchParams({ h: starts.join(",") }).toString());
      if (!starts.length) { out.innerHTML = ""; current = null; return; }
      const avg = averageHeatInterval(starts);
      const next = predictNextHeat(starts);
      const interval = avg ?? DEFAULT_HEAT_INTERVAL;
      const after = addDays(next, interval);
      const testFrom = addDays(next, 4), testTo = addDays(next, 5);
      const left = daysBetween(todayIso(), next);
      const status = left > 0 ? fill(P.inDays, { n: left }) : left === 0 ? P.today : fill(P.overdue, { n: -left });
      current = { next, after, testFrom };
      out.innerHTML = `
        <div class="result-hero"><span class="label">${esc(P.next)}</span><span class="date">${esc(long(next))}</span></div>
        <p class="result-sub">${esc(status)} ${esc(avg != null ? fill(P.basedAvg, { n: avg, m: nf(avg / 30.44, 1) }) : P.basedDefault)}</p>
        <div class="targets">
          <div class="target"><div class="k">${esc(P.testing)}</div><div class="v">${esc(short(testFrom))} – ${esc(short(testTo))}</div><div class="k">${esc(P.testingS)}</div></div>
          <div class="target"><div class="k">${esc(P.interval)}</div><div class="v">${esc(fill(P.daysN, { n: interval }))}</div><div class="k">${esc(avg != null ? fill(P.fromN, { n: starts.length }) : P.typical)}</div></div>
          <div class="target"><div class="k">${esc(P.following)}</div><div class="v">${esc(short(after))}</div><div class="k">${esc(P.followingS)}</div></div>
        </div>
        ${left < -30 ? `<p class="note">${esc(P.lateNote)}</p>` : ""}
        ${actions(true)}`;
    }

    bindActions(host, () => current && {
      name: `next-heat-${current.next}.ics`,
      text: ics([
        { date: addDays(current.next, -7), title: P.calSoon, desc: P.calSoonS },
        { date: current.next, title: P.calNext, desc: P.calNextS },
        { date: current.testFrom, title: P.calTest, desc: P.testingS }
      ], "Dog heat cycle calculator")
    });
    form.addEventListener("change", render);
    form.addEventListener("input", render);
    render();
  }

  /* ---------------- puppy weight ---------------- */

  function puppy(host) {
    const P = T.puppy;
    const unitInit = params.get("u") === "oz" ? "oz" : (store.get("sd.pup.unit") || "g");
    host.innerHTML = `
      <form class="calc" onsubmit="return false">
        <div class="calc-fields">
          <label class="field">${esc(P.fUnit)}<select name="u"><option value="g">${esc(P.grams)}</option><option value="oz">${esc(P.ounces)}</option></select></label>
          <label class="field">${esc(P.fBirth)}<input type="number" name="b" min="1" step="any" inputmode="decimal"></label>
          <label class="field">${esc(P.fAge)}<input type="number" name="a" min="0" max="60" step="1" inputmode="numeric"></label>
          <label class="field">${esc(P.fNow)}<input type="number" name="w" min="1" step="any" inputmode="decimal"></label>
        </div>
        <div class="calc-result" aria-live="polite"></div>
      </form>`;
    const form = host.querySelector("form");
    const out = host.querySelector(".calc-result");
    form.elements.u.value = unitInit;
    form.elements.b.value = params.get("b") || "";
    form.elements.a.value = params.get("a") || "";
    form.elements.w.value = params.get("w") || "";
    const GPO = 28.349523125;

    function render() {
      const u = form.elements.u.value;
      const b = parseFloat(form.elements.b.value), a = parseInt(form.elements.a.value, 10), w = parseFloat(form.elements.w.value);
      store.set("sd.pup.unit", u);
      setUrl(new URLSearchParams({ u, b: form.elements.b.value, a: form.elements.a.value, w: form.elements.w.value }).toString());
      if (!(b > 0)) { out.innerHTML = `<p class="result-sub">${esc(P.empty)}</p>`; return; }
      const toG = x => (u === "oz" ? x * GPO : x);
      const show = g => (u === "oz" ? `${nf(g / GPO, 1)} oz` : `${nf(g, 0)} g`);
      const target = show(toG(b) * 2);
      if (!(w > 0) || !(a >= 0)) {
        out.innerHTML = `<div class="result-hero"><span class="label">${esc(P.target)}</span><span class="date">${esc(target)}</span></div>
          <p class="result-sub">${esc(P.targetOnly)}</p>`;
        return;
      }
      const r = puppyCheck(toG(b), toG(w), a);
      const sign = r.change >= 0 ? "+" : "−";
      out.innerHTML = `
        <div class="result-hero"><span class="label">${esc(P.flagLabel)}</span><span class="date">${esc(P.flags[r.flag])}</span></div>
        <p class="result-sub">${esc(P.flagText[r.flag])}</p>
        <div class="targets">
          <div class="target"><div class="k">${esc(P.change)}</div><div class="v">${sign}${esc(nf(Math.abs(r.change), 0))} %</div><div class="k">${esc(fill(P.since, { n: a }))}</div></div>
          <div class="target"><div class="k">${esc(P.perDay)}</div><div class="v">${r.perDay == null ? "–" : esc(nf(r.perDay, 1)) + " %"}</div><div class="k">${esc(P.perDayS)}</div></div>
          <div class="target"><div class="k">${esc(P.target)}</div><div class="v">${esc(target)}</div><div class="k">${esc(P.targetS)}</div></div>
        </div>
        ${actions()}`;
    }
    bindActions(host, null);
    form.addEventListener("change", render);
    form.addEventListener("input", render);
    render();
  }

  const MOUNT = { pregnancy, progesterone, heat, puppy };
  document.querySelectorAll("[data-sd-calc]").forEach(el => {
    const fn = MOUNT[el.dataset.sdCalc];
    if (fn) fn(el);
  });
})();
